package de.sebaro_ventures.design.designsystem

import android.app.Notification
import android.app.PendingIntent
import android.content.Context
import android.os.Build
import androidx.annotation.DrawableRes
import androidx.annotation.RequiresApi

/**
 * One action of a phone notification (spec/07 §4.9, D104 (45)): [label] is a verb or a time with its target from the
 * app's strings („Erledigt“, „In 30 Min.“), never „OK“, „Öffnen“ or „Später“ alone, and never a destructive action
 * (a notification cannot ask first, D39). The action does not close the notification: the receiver of [intent] cancels
 * it once it has done the action.
 */
class SbNotificationAction(val label: String, val intent: PendingIntent)

/**
 * The content of a phone notification (spec/07 §4.9, D104 (45)): [title] names the thing („Wasser trinken“), [text]
 * is one calm sentence or null, at most two [actions]. [isPrivate] content (a thought, a note, a health value) carries
 * its title alone, so the lock screen shows no more whatever the person's setting. A blank title, a third action or a
 * text on private content throws IllegalArgumentException.
 */
class SbNotificationContent(
    val title: String,
    val text: String? = null,
    val actions: List<SbNotificationAction> = emptyList(),
    val isPrivate: Boolean = false,
) {
    init {
        require(title.isNotBlank()) { "the title names the thing (spec/07 §4.9)" }
        require(actions.count() <= 2) { "at most two actions (spec/07 §4.9, D104 (45)), not ${actions.count()}" }
        require(!isPrivate || text == null) { "private content carries its title alone (spec/07 §4.9, D104 (45))" }
    }
}

/**
 * A notification builder for [content] on [channelId] (Android 8 and later, where every notification has a channel):
 * [smallIcon] (the brand export's R.drawable.ic_stat_notify), the title, the text in full when expanded, the actions
 * as words, and for private content a lock-screen version with the title alone; other content keeps Android's default
 * visibility, so the person's lock-screen setting decides. No colour, sound, category or priority: the app adds those
 * and its content intent on the returned builder.
 */
@RequiresApi(Build.VERSION_CODES.O)
fun sbNotification(
    context: Context,
    channelId: String,
    content: SbNotificationContent,
    @DrawableRes smallIcon: Int,
): Notification.Builder {
    val b = Notification.Builder(context, channelId)
        .setSmallIcon(smallIcon)
        .setContentTitle(content.title)
    content.text?.let { b.setContentText(it).setStyle(Notification.BigTextStyle().bigText(it)) }
    // Android 7 and later show an action as its word; the icon is not drawn, so none is passed
    content.actions.forEach { b.addAction(Notification.Action.Builder(null as android.graphics.drawable.Icon?, it.label, it.intent).build()) }
    if (content.isPrivate) {
        val public = Notification.Builder(context, channelId)
            .setSmallIcon(smallIcon)
            .setContentTitle(content.title)
            .build()
        b.setVisibility(Notification.VISIBILITY_PRIVATE).setPublicVersion(public)
    }
    return b
}
